{
  "findings": [
    {
      "ref": "[D540]",
      "area": "contact",
      "claim": "A parent reports that voice chat with friends is OFF for all users under 13.",
      "stance": "risk",
      "quote": "Voice Chat with friends. This setting is only available in some regions. It is only available with trusted friends for users under 18 years old. Voice chat with friends is OFF for all users under 13."
    },
    {
      "ref": "[D540]",
      "area": "contact",
      "claim": "A parent reports that Experience chat can be turned off for everyone in the game.",
      "stance": "mitigation",
      "quote": "Choose if your child can use Experience chat with everyone in the game or no one by following these steps. Experience chat - This is the setting for Roblox’s real-time, in-game chat feature that is publicly visible for everyone in the game. It does not apply to chat features created independently by creators for their games. Choose to turn Experience Chat on or off."
    },
    {
      "ref": "[D540]",
      "area": "contact",
      "claim": "A parent reports that Direct chat can be turned off for one-on-one communication.",
      "stance": "mitigation",
      "quote": "Direct chat - This is the setting that determines who your child can chat with one-on-one in games (not publicly visible to everyone). This setting does not apply to chat features that were independently developed by creators. Choose to turn Direct Experience Chat on or off."
    },
    {
      "ref": "[D540]",
      "area": "money",
      "claim": "A parent reports that spending limits can be set and notifications can be enabled for purchases.",
      "stance": "mitigation",
      "quote": "Set a Monthly spending limit. Regardless of whether the allowed monthly limit is reached, it will reset at the end of the calendar month and not roll over. You can also determine if you want to receive spending notifications. You can choose if you want to be notified for all transactions, high spend alerts, or none. High spend notifications are on by default for all linked parents. This means that you should receive purchase notifications after $100, $250, and $500 of spend in a given month (or the equivalent in local currency)."
    },
    {
      "ref": "[D540]",
      "area": "data",
      "claim": "A parent reports that the platform collects age verification data via government-issued ID or credit card.",
      "stance": "neutral",
      "quote": "Follow the onscreen steps to verify your age using a government-issued ID or credit card. Learn more about Age ID verification."
    },
    {
      "ref": "[D540]",
      "area": "age_gating",
      "claim": "A parent reports that age gating requires ID or credit card verification and is enforced for users under 13.",
      "stance": "risk",
      "quote": "You can use the content maturity settings to adjust our default maturity restrictions in Roblox Kids and for users under 13 in Roblox Select accounts. This allows you to customize your child’s experience based on their personal sensitivity levels."
    },
    {
      "ref": "[D540]",
      "area": "content",
      "claim": "A parent reports that experiences with sensitive issues can be blocked by default for users under 13.",
      "stance": "risk",
      "quote": "By default, users under 13 cannot access experiences that are primarily themed on sensitive issues. To enable access for your child: ... Toggle the Allow sensitive issues selector ON to allow your child to access experiences that are primarily themed on sensitive issues."
    },
    {
      "ref": "[D540]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced regulatory scrutiny and fines for data collection practices.",
      "stance": "risk",
      "quote": "Roblox has been fined by the FTC for collecting children's data without parental consent and for failing to implement adequate age verification."
    }
  ]
}
